-- Generated by scripts/check_oracle.py --dump-ddl
-- Target: Oracle 19c+, schema AIWECHAT. Review only; backend startup
-- runs the same create_all() automatically (checkfirst).

CREATE TABLE app_user (
	id INTEGER GENERATED BY DEFAULT AS IDENTITY, 
	openid VARCHAR2(64 CHAR) NOT NULL, 
	role VARCHAR2(16 CHAR) NOT NULL, 
	name VARCHAR2(64 CHAR) NOT NULL, 
	avatar_url VARCHAR2(500 CHAR), 
	created_at TIMESTAMP NOT NULL, 
	last_login TIMESTAMP, 
	PRIMARY KEY (id)
);

CREATE TABLE child (
	id INTEGER GENERATED BY DEFAULT AS IDENTITY, 
	name VARCHAR2(64 CHAR) NOT NULL, 
	parent_wxid VARCHAR2(64 CHAR), 
	group_nick_pattern VARCHAR2(128 CHAR), 
	first_seen TIMESTAMP NOT NULL, 
	last_seen TIMESTAMP NOT NULL, 
	notes CLOB, 
	PRIMARY KEY (id)
);

CREATE TABLE auth_token (
	id INTEGER GENERATED BY DEFAULT AS IDENTITY, 
	token VARCHAR2(128 CHAR) NOT NULL, 
	user_id INTEGER NOT NULL, 
	created_at TIMESTAMP NOT NULL, 
	expires_at TIMESTAMP, 
	PRIMARY KEY (id), 
	FOREIGN KEY(user_id) REFERENCES app_user (id) ON DELETE CASCADE
);

CREATE TABLE classroom (
	id INTEGER GENERATED BY DEFAULT AS IDENTITY, 
	name VARCHAR2(64 CHAR) NOT NULL, 
	code VARCHAR2(16 CHAR) NOT NULL, 
	teacher_id INTEGER NOT NULL, 
	created_at TIMESTAMP NOT NULL, 
	PRIMARY KEY (id), 
	FOREIGN KEY(teacher_id) REFERENCES app_user (id) ON DELETE CASCADE
);

CREATE TABLE homework (
	id INTEGER GENERATED BY DEFAULT AS IDENTITY, 
	child_id INTEGER NOT NULL, 
	group_roomid VARCHAR2(64 CHAR) NOT NULL, 
	msg_id NUMBER(19) NOT NULL, 
	media_type VARCHAR2(16 CHAR) NOT NULL, 
	media_path VARCHAR2(500 CHAR), 
	raw_transcript CLOB, 
	is_homework INTEGER NOT NULL, 
	feedback CLOB, 
	teacher_review CLOB, 
	created_at TIMESTAMP NOT NULL, 
	submit_user_id INTEGER, 
	classroom_id INTEGER, 
	child_name VARCHAR2(64 CHAR), 
	PRIMARY KEY (id), 
	CONSTRAINT uq_homework_room_msg UNIQUE (group_roomid, msg_id), 
	FOREIGN KEY(child_id) REFERENCES child (id) ON DELETE CASCADE
);

CREATE TABLE growth_checkin (
	id INTEGER GENERATED BY DEFAULT AS IDENTITY, 
	classroom_id INTEGER NOT NULL, 
	child_name VARCHAR2(64 CHAR) NOT NULL, 
	teacher_id INTEGER, 
	checkin_date DATE NOT NULL, 
	note CLOB, 
	created_at TIMESTAMP NOT NULL, 
	updated_at TIMESTAMP NOT NULL, 
	PRIMARY KEY (id), 
	CONSTRAINT uq_checkin_class_child_date UNIQUE (classroom_id, child_name, checkin_date), 
	FOREIGN KEY(classroom_id) REFERENCES classroom (id) ON DELETE CASCADE, 
	FOREIGN KEY(teacher_id) REFERENCES app_user (id) ON DELETE SET NULL
);

CREATE TABLE growth_template (
	id INTEGER GENERATED BY DEFAULT AS IDENTITY, 
	classroom_id INTEGER, 
	code VARCHAR2(16 CHAR) NOT NULL, 
	label VARCHAR2(32 CHAR) NOT NULL, 
	multi_select INTEGER NOT NULL, 
	sort_order INTEGER NOT NULL, 
	active INTEGER NOT NULL, 
	PRIMARY KEY (id), 
	CONSTRAINT uq_template_class_code UNIQUE (classroom_id, code), 
	FOREIGN KEY(classroom_id) REFERENCES classroom (id) ON DELETE CASCADE
);

CREATE TABLE growthmetric (
	id INTEGER GENERATED BY DEFAULT AS IDENTITY, 
	child_id INTEGER NOT NULL, 
	homework_id INTEGER NOT NULL, 
	dimension VARCHAR2(64 CHAR) NOT NULL, 
	score FLOAT NOT NULL, 
	note CLOB, 
	created_at TIMESTAMP NOT NULL, 
	PRIMARY KEY (id), 
	FOREIGN KEY(child_id) REFERENCES child (id) ON DELETE CASCADE, 
	FOREIGN KEY(homework_id) REFERENCES homework (id) ON DELETE CASCADE
);

CREATE TABLE membership (
	id INTEGER GENERATED BY DEFAULT AS IDENTITY, 
	user_id INTEGER NOT NULL, 
	classroom_id INTEGER NOT NULL, 
	child_name VARCHAR2(64 CHAR) NOT NULL, 
	created_at TIMESTAMP NOT NULL, 
	PRIMARY KEY (id), 
	CONSTRAINT uq_membership_user_class UNIQUE (user_id, classroom_id), 
	FOREIGN KEY(user_id) REFERENCES app_user (id) ON DELETE CASCADE, 
	FOREIGN KEY(classroom_id) REFERENCES classroom (id) ON DELETE CASCADE
);

CREATE TABLE report_batch (
	id INTEGER GENERATED BY DEFAULT AS IDENTITY, 
	classroom_id INTEGER NOT NULL, 
	teacher_id INTEGER, 
	report_type VARCHAR2(8 CHAR) NOT NULL, 
	period_start DATE NOT NULL, 
	period_end DATE NOT NULL, 
	status VARCHAR2(16 CHAR) NOT NULL, 
	total INTEGER NOT NULL, 
	succeeded INTEGER NOT NULL, 
	failed_count INTEGER NOT NULL, 
	error_msg VARCHAR2(1000 CHAR), 
	started_at TIMESTAMP, 
	finished_at TIMESTAMP, 
	created_at TIMESTAMP NOT NULL, 
	PRIMARY KEY (id), 
	CONSTRAINT uq_batch_class_type_start UNIQUE (classroom_id, report_type, period_start), 
	CONSTRAINT ck_batch_type CHECK (report_type in ('day', 'week')), 
	CONSTRAINT ck_batch_status CHECK (status in ('pending', 'running', 'done', 'partial', 'failed')), 
	FOREIGN KEY(classroom_id) REFERENCES classroom (id) ON DELETE CASCADE, 
	FOREIGN KEY(teacher_id) REFERENCES app_user (id) ON DELETE SET NULL
);

CREATE TABLE child_report (
	id INTEGER GENERATED BY DEFAULT AS IDENTITY, 
	batch_id INTEGER NOT NULL, 
	classroom_id INTEGER NOT NULL, 
	child_name VARCHAR2(64 CHAR) NOT NULL, 
	report_type VARCHAR2(8 CHAR) NOT NULL, 
	period_start DATE NOT NULL, 
	period_end DATE NOT NULL, 
	status VARCHAR2(16 CHAR) NOT NULL, 
	content CLOB, 
	teacher_edit CLOB, 
	is_published INTEGER NOT NULL, 
	published_at TIMESTAMP, 
	error_msg VARCHAR2(1000 CHAR), 
	created_at TIMESTAMP NOT NULL, 
	updated_at TIMESTAMP NOT NULL, 
	PRIMARY KEY (id), 
	CONSTRAINT uq_report_batch_child UNIQUE (batch_id, child_name), 
	CONSTRAINT uq_report_child_period UNIQUE (classroom_id, child_name, report_type, period_start), 
	CONSTRAINT ck_report_type CHECK (report_type in ('day', 'week')), 
	CONSTRAINT ck_report_status CHECK (status in ('pending', 'running', 'done', 'failed')), 
	FOREIGN KEY(batch_id) REFERENCES report_batch (id) ON DELETE CASCADE, 
	FOREIGN KEY(classroom_id) REFERENCES classroom (id) ON DELETE CASCADE
);

CREATE TABLE growth_checkin_item (
	id INTEGER GENERATED BY DEFAULT AS IDENTITY, 
	checkin_id INTEGER NOT NULL, 
	category_code VARCHAR2(16 CHAR) NOT NULL, 
	option_label VARCHAR2(32 CHAR) NOT NULL, 
	note VARCHAR2(400 CHAR), 
	PRIMARY KEY (id), 
	CONSTRAINT uq_checkin_item UNIQUE (checkin_id, category_code, option_label), 
	FOREIGN KEY(checkin_id) REFERENCES growth_checkin (id) ON DELETE CASCADE
);

CREATE TABLE growth_template_option (
	id INTEGER GENERATED BY DEFAULT AS IDENTITY, 
	template_id INTEGER NOT NULL, 
	label VARCHAR2(32 CHAR) NOT NULL, 
	sort_order INTEGER NOT NULL, 
	PRIMARY KEY (id), 
	CONSTRAINT uq_template_option_label UNIQUE (template_id, label), 
	FOREIGN KEY(template_id) REFERENCES growth_template (id) ON DELETE CASCADE
);
